  // MIME type of the file (e.g. "image/png", "application/pdf")
  media_type: string;
  // Upload path relative to cloud-content (e.g. "my-project/photo.png" or just "photo.png"). Defaults to cloud-content/<filename> if no directory is given.
  path: string;
  // When true (default), shortens presigned block-transfer URLs and related finalize/extend links so responses use less context. AI agents should keep this true.
  shorten_block_upload_urls?: boolean;
}): Promise<CallToolResult<{
