  // 1-12 total placements per call; NEVER exceed 12 — split larger sets into multiple sequential calls. Each url/assetId in an entry counts as one placement. PREFERRED types: presignedUrl (https URLs), generationUrn (Firefly URNs). USE WITH CAUTION: rawBlob — LLM/chat clients truncate large base64 strings, causing decode errors.
  items: Array<{
  type: "presignedUrl";
  // PREFERRED. One or more time-limited https URLs the server fetches directly. Each URL counts as one image placement toward the 1-12 per-call limit.
  urls: Array<string>;
} | {
  // PREFERRED. One or more Firefly generation URNs (carry provenance metadata). Each URN counts as one image placement toward the 1-12 per-call limit.
  assetIds: Array<string>;
  type: "generationUrn";
} | {
  // USE WITH CAUTION in chat / LLM clients — models truncate large base64 strings, causing the upload to fail. Use presignedUrl or generationUrn instead. If you must send rawBlob, provide the COMPLETE base64 of the file with no newlines or data: prefix.
  bytesBase64: string;
  // Image height in pixels. Must match the actual decoded dimensions — the server validates this.
  height: number;
  // Image MIME type, e.g. image/jpeg, image/png, image/webp.
  mimeType: string;
