declare const tools: { mcp__codex_apps__robinhood_cancel_option_exercise(args: {
  // Brokerage account that owns the exercise. Must be agentic_allowed=true.
  account_number: string;
  // Option instrument UUID — the same option_id used for exercise_option. The tool looks up the queued exercise for this option and cancels it.
