  // 'open' (new position) or 'close' (existing position). To close a long use sell; to close a short use buy.
  position_effect: string;
  // Contracts for this leg per unit of the order's quantity. Defaults to 1.
  ratio_quantity?: number;
  // 'buy' or 'sell'.
  side: string;
}>;
  // 'regular_hours' (default), 'regular_curb_hours', or 'regular_curb_overnight_hours'. Non-limit-immediate orders only place in regular_hours. CURB requires an index chain with extended_hours_state='enabled'.
  market_hours?: string;
  // Limit price per contract. Required for limit/stop_limit; must be omitted for market/stop_market.
  price?: string;
  // Positive integer contract count.
  quantity: string;
  // Idempotency key (UUID). Generate once per logical order and re-send on retry. Omitting falls back to a server-generated key.
  ref_id?: string;
  // Stop trigger price per contract. Required for stop_limit/stop_market; must be omitted for limit/market.
  stop_price?: string;
  // 'gfd' (default) or 'gtc'. Market orders must be 'gfd'.
  time_in_force?: string;
  // 'limit' (default), 'market', 'stop_limit', or 'stop_market'. Should match the type the user reviewed.
  type?: string;
}): Promise<CallToolResult<{
  // Tool-specific result payload; see the inner properties for fields.
  data: {
  // Newly-created order. Same shape as get_option_orders orders[].
  order?: null | {
  // Contracts cancelled.
  canceled_quantity: string;
  // Option chain UUID.
  chain_id: string;
  // Underlying ticker (e.g. 'AAPL', 'SPX').
  chain_symbol: string;
  // Recognized closing strategy; null when not derivable.
  closing_strategy: null | string;
  // ISO 8601 creation time.
  created_at: string;
  // 'debit' (you pay) or 'credit' (you receive) on the overall order.
  direction: string;
  // Order UUID; needed by cancel_option_order.
  id: string;
  // True when this order is eligible for replace_option_order — cancelable, not already pending-cancel, and not in an in-flight replacement chain.
  is_replaceable: boolean;
  // ISO 8601 time of the most recent fill/cancel/reject; null on a brand-new unfilled order.
  last_transaction_at: null | string;
  // Per-leg detail; single-leg orders are standard.
  legs: null | Array<{
  // Per-fill detail for this leg.
  executions?: null | Array<{
  // Execution UUID.
  id: string;
  // Fill price per contract.
  price: string;
  // Contracts filled in this execution.
  quantity: string;
  // YYYY-MM-DD settlement date.
  settlement_date: string;
  // ISO 8601 fill time.
  timestamp: string;
  // YYYY-MM-DD trade date.
  trade_date: string;
}>;
  // YYYY-MM-DD contract expiration.
  expiration_date: string;
  // Leg UUID.
  id: string;
  // Option instrument UUID. May be omitted on legacy orders that only carry the option URL.
  option_id?: string;
  // 'call' or 'put'.
  option_type: string;
  // 'open' or 'close'.
  position_effect: string;
  // Contracts for this leg per unit of the order's quantity.
  ratio_quantity: number;
  // 'buy' or 'sell' for this leg.
  side: string;
  // Contract strike.
  strike_price: string;
}>;
  // 'regular_hours', 'regular_curb_hours', or 'regular_curb_overnight_hours'.
  market_hours: string;
  // Recognized opening strategy (e.g. 'long_call', 'iron_condor'); null when not derivable.
  opening_strategy: null | string;
  // Contracts still working.
  pending_quantity: string;
  // Source that placed the order: 'user' (app), 'agentic' (MCP), 'recurring', 'drip', etc.
  placed_agent: string;
  // Total order premium (price × quantity × multiplier).
  premium: string;
  // Limit price per contract.
  price: string;
  // Premium realized on fills so far.
  processed_premium: string;
  // Contracts filled so far.
  processed_quantity: string;
  // Contracts originally requested.
  quantity: string;
  // Free-text reason when state is 'rejected'.
  reject_reason?: string;
  // Lifecycle state: queued, confirmed, partially_filled, filled, rejected, cancelled, failed, voided, pending_cancelled.
  state: string;
  // Stop trigger; null for non-stop orders.
  stop_price: null | string;
  // 'gfd' or 'gtc'.
  time_in_force: string;
  // Contract multiplier; typically '100'.
  trade_value_multiplier: string;
  // 'immediate' or 'stop'.
  trigger: string;
  // Order type: 'limit' or 'market'. Combine with trigger to recover user-facing type: limit+immediate=limit, market+immediate=market, limit+stop=stop_limit, market+stop=stop_market.
  type: string;
  // ISO 8601 last update time.
  updated_at?: string;
};
};
  // The order has been submitted — not necessarily filled. Describe with state. Summarize chain_symbol, opening_strategy or closing_strategy, quantity, price, direction; remind the user it may not have filled and that they can check status or cancel via id. Source chain_symbol from the response directly. On error, the order was NOT placed; report the error verbatim. CURB-rejection errors mean market_hours is incompatible with the chain or the CURB session is closed — suggest 'regular_hours' or waiting for the session.
  guide: string;
}>>; };
