  // The next_cursor returned by the preceding read_messages response. Use it unchanged to read the next page, with the same chat_guid, from, to, and unread_only values.
  cursor?: string;
  // Include messages at or after this ISO-8601 date-time.
  from?: string;
  limit?: number;
  // Include messages before this ISO-8601 date-time.
  to?: string;
  // When true, return only unread messages.
  unread_only?: boolean;
}): Promise<CallToolResult<{ chats: Array<{ chat_guid: string; display_name?: string; local_ref: string; }>; messages: Array<{ attachments?: Array<{ filename?: string; id: string; mime_type?: string; size_bytes?: number; }>; body?: string; chat: string; date: string; is_unread?: boolean; sender: string; }>; next_cursor?: string; senders: Array<{ handle: string; local_ref: string; name?: string; service?: string; }>; } | { message: string; }>>; };
